#pragma once
#include "projection_molecule.hpp"
#include "next/chemistry/edit.hpp"
#include "nickname_catalog.hpp"
namespace r62 { namespace projection_molecule {
// Upgrade only recognized legacy projection groups. Work on a candidate so an
// ambiguous drawing is retained intact instead of being partially interpreted.
inline bool migrateGroup(Document& d,ObjectId groupId){
    auto g=d.groups().alive(groupId);if(!g)return false;int k=g->label=="Fischer projection"?0:g->label=="Sawhorse projection"?1:g->label=="Newman projection"?2:-1;if(k<0)return false;auto members=g->members;
    std::vector<std::pair<Vec2,Vec2>> lines;std::vector<ObjectId> captions;Vec2 circle;double circleRadius=0;
    for(auto ref:members){if(ref.kind==ObjectKind::Text){captions.push_back(ref.id);continue;}if(ref.kind!=ObjectKind::Path)return false;auto p=d.paths().alive(ref.id);if(!p)return false;if(!p->closed&&p->points.size()==2){lines.push_back({p->points.front(),p->points.back()});}else if(p->closed){Box b;for(auto point:p->points)b.add(point);double r=(b.max.x-b.min.x)*.5;if(r>circleRadius){circleRadius=r;circle=(b.min+b.max)*.5;}}else return false;}
    if(lines.empty())return false;
    struct Tip{int core;Vec2 point;int order;Tip(int c,Vec2 p,int o=1):core(c),point(p),order(o){}};
    std::vector<Vec2> centres;std::vector<Tip> tips;Vec2 stemAxis(0,1);
    if(k==2){if(circleRadius<=0||lines.size()!=6)return false;centres={circle,circle};int counts[2]={0,0};for(auto line:lines){auto a=line.first,b=line.second;if(length(a-circle)>length(b-circle))std::swap(a,b);int plane=length(a-circle)<circleRadius*.15?0:1;if(plane&&std::abs(length(a-circle)-circleRadius)>circleRadius*.1)return false;tips.emplace_back(plane,b);++counts[plane];}if(counts[0]!=3||counts[1]!=3)return false;}
    else if(k==1){std::vector<Vec2> vertices;std::vector<std::pair<int,int>> edges;auto vertex=[&](Vec2 p){for(size_t i=0;i<vertices.size();++i)if(length(p-vertices[i])<.01)return int(i);vertices.push_back(p);return int(vertices.size()-1);};for(auto line:lines){int a=vertex(line.first),b=vertex(line.second);edges.push_back({a,b});}std::vector<int> hubs;for(size_t i=0;i<vertices.size();++i){int degree=0;for(auto e:edges)degree+=e.first==int(i)||e.second==int(i);if(degree==4)hubs.push_back(int(i));}if(hubs.size()!=2||lines.size()!=7)return false;auto span=[&](int hub){double result=0;for(auto e:edges){int n=e.first==hub?e.second:e.second==hub?e.first:-1;if(n>=0&&n!=hubs[0]&&n!=hubs[1])result+=length(vertices[n]-vertices[hub]);}return result;};if(span(hubs[0])<span(hubs[1]))std::swap(hubs[0],hubs[1]);centres={vertices[hubs[0]],vertices[hubs[1]]};for(int plane=0;plane<2;++plane)for(auto e:edges){int n=e.first==hubs[plane]?e.second:e.second==hubs[plane]?e.first:-1;if(n>=0&&n!=hubs[1-plane])tips.emplace_back(plane,vertices[n]);}}
    else{auto stem=*std::max_element(lines.begin(),lines.end(),[](const std::pair<Vec2,Vec2>& a,const std::pair<Vec2,Vec2>& b){return lengthSq(a.second-a.first)<lengthSq(b.second-b.first);});double span=length(stem.second-stem.first);if(span<.01)return false;stemAxis=(stem.second-stem.first)*(1/span);struct Branch{double t;Vec2 from,to;};std::vector<Branch> branches;for(auto line:lines){if(length(line.first-stem.first)<.01&&length(line.second-stem.second)<.01)continue;auto distance=[&](Vec2 p){auto v=p-stem.first;return std::abs(v.x*stemAxis.y-v.y*stemAxis.x);};auto a=line.first,b=line.second;if(distance(a)>distance(b))std::swap(a,b);if(distance(a)>span*.03)return false;branches.push_back({dot(a-stem.first,stemAxis),a,b});}std::sort(branches.begin(),branches.end(),[](const Branch& a,const Branch& b){return a.t<b.t;});if(branches.size()%2)return false;for(size_t i=0;i<branches.size();i+=2){auto a=branches[i],b=branches[i+1];if(std::abs(a.t-b.t)>span*.03)return false;int core=int(centres.size());centres.push_back((a.from+b.from)*.5);auto u=a.to-a.from,v=b.to-b.from;if(dot(u,v)>0)tips.emplace_back(core,(a.to+b.to)*.5,2);else{tips.emplace_back(core,a.to);tips.emplace_back(core,b.to);}}if(centres.empty())return false;tips.emplace_back(0,stem.first);tips.emplace_back(int(centres.size()-1),stem.second);}
    if(captions.size()>tips.size())return false;
    std::vector<std::string> labels(tips.size());std::set<size_t> used;
    for(auto id:captions){auto text=d.texts().alive(id);if(!text)return false;size_t best=tips.size();double distance=1e100;for(size_t i=0;i<tips.size();++i)if(!used.count(i)){auto p=text->position;double w=std::max(1.,double(d.plainText(id).size())*text->size*.5);if(text->format.align==uint8_t(TextAlign::Right))p.x-=w*.5;else if(text->format.align==uint8_t(TextAlign::Left))p.x+=w*.5;double score=length(p-tips[i].point);if(score<distance){distance=score;best=i;}}if(best==tips.size()||distance>d.defaultBondLength()*3)return false;used.insert(best);labels[best]=d.plainText(id);}
    std::vector<ObjectId> cores;for(size_t i=0;i<centres.size();++i){ObjectId id;if(!d.addAtom(centres[i],6,&id).ok())return false;mark(d,id,k,k?int(i):0);cores.push_back(id);}for(size_t i=1;i<cores.size();++i){ObjectId edge;if(!d.addBond(cores[i-1],cores[i],&edge).ok())return false;}
    for(size_t i=0;i<tips.size();++i){ObjectId id,edge;if(!d.addAtom(tips[i].point,6,&id).ok()||!d.addBond(cores[tips[i].core],id,&edge).ok())return false;if(tips[i].order==2)d.setBondOrder(edge,BondOrder::Double);auto label=labels[i];if(!label.empty()){CommandContext ctx(d);if(!chemistry::setLabelTextCommand(id,label,{},nullptr).execute(ctx).ok())return false;auto nickname=nickdata::find(label);auto alias=nickdata::findAlias(label);if(nickname||alias){auto sem=d.atoms().alive(id)->semantics;sem.nodeType=uint8_t(NodeType::Nickname);sem.implicitHydrogens=-1;d.setAtomSemantics(id,sem);d.setAtomLabel(id,label);d.extensions(ObjectRef(ObjectKind::Atom,id)).set("studio.nickname.fragment",nickname?nickname->fragment:alias->fragment);}}}
    seed(d);
    // Fischer depth is tied to the stem, including rotated legacy drawings.
    if(k==0)for(auto c:cores)for(auto bid:d.incidentBonds(c)){auto b=d.bonds().alive(bid);auto n=b->beginAtom==c?b->endAtom:b->beginAtom;auto v=d.atoms().alive(n)->position-d.atoms().alive(c)->position;v=v*(1/std::max(1e-9,length(v)));std::ostringstream out;out<<v.x<<' '<<-v.y<<' '<<(std::abs(dot(v,stemAxis))>.5?-1:1);d.extensions(ObjectRef(ObjectKind::Bond,bid)).set(vectorKey(*b,c),out.str());}
    for(auto ref:members)d.removeObject(ref);d.removeObject(ObjectRef(ObjectKind::Group,groupId));return true;
}
inline void migrateLegacy(Document& d){std::vector<ObjectId> groups;for(const auto& g:d.groups().records())if(g.isAlive()&&(g.label=="Fischer projection"||g.label=="Sawhorse projection"||g.label=="Newman projection"))groups.push_back(g.id);for(auto id:groups){Document candidate=d;if(migrateGroup(candidate,id))d=std::move(candidate);}}
} }
